        "title": "EnMS-2.2 有色金属",
        "summary": "从能源管理体系认证角度看，有色金属不是一个简单的行业名称，而是一组以采矿选矿、火法冶炼、湿法冶金、电解精炼、压延加工、再生利用和公辅能源系统为核心的用能过程集合。不同细分方向的主要能源使用和专业能力要求差异显著。例如，电解铝以电力消耗和电解槽控制为核心，铜铅锌火法冶炼以炉窑、富氧熔炼、余热回收和烟气制酸为重点，湿法冶金以浸出、萃取、电积、蒸发和溶液循环系统为...",
